1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on conflict):
13	 * rejects the request with 409 via {@link CityAtCapacityException} when the request's city already
14	 * contains {@link #MAX_OWNERS_PER_CITY} or more owners, compared case-insensitively with collapsed
15	 * whitespace.
16	 */
17	public class CheckOwnerCityCapacity {
18	
19	    /** Maximum owners allowed per city; the next create in a full city is rejected. */
20	    static final int MAX_OWNERS_PER_CITY = 50;
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws CityAtCapacityException {
24	        String city = normalize(request.getCity());
25	        int count = 0;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (city.equals(normalize(existing.getCity())) && ++count >= MAX_OWNERS_PER_CITY) {
28	                throw new CityAtCapacityException(request.getCity());
29	            }
30	        }
31	    }
32	
33	    /** Lower-case and collapse runs of whitespace so comparison is case- and whitespace-insensitive. */
34	    private static String normalize(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
39	    }
40	}
