91	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more owners, plus 3 when
92	     * tenure spans at least one elapsed fiscal year (fiscal years start 1 July). Because a newly
93	     * created owner registers within the current fiscal year it has zero tenure, so the tenure points
94	     * are only earned on later reads.
95	     */
96	    protected Integer membershipPoints(Owner owner) {
97	        int points = 0;
98	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
99	            points += 2;
100	        }
101	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount().intValue() == 0) {
102	            points += 1;
103	        }
104	        if (householdSize(owner) >= 3) {
105	            points += 2;
