121	     * cap applies. The household is replayed in creation (id) order so each member is capped at one
122	     * above the running maximum of the earlier members' already-capped levels.
123	     */
124	    protected Integer membershipLevel(Owner owner) {
125	        String householdId = owner.getHouseholdId();
126	        Integer id = owner.getId();
127	        if (householdId == null || id == null) {
128	            return uncappedLevel(owner);
129	        }
130	        java.util.List<Owner> members = new java.util.ArrayList<>();
131	        for (Owner existing : ownerRepository.findAll()) {
132	            if (existing.getId() != null && existing.getId() <= id
133	                    && householdId.equals(existing.getHouseholdId())) {
134	                members.add(existing);
135	            }
136	        }
137	        members.sort(java.util.Comparator.comparingInt(Owner::getId));
138	        Integer runningMax = null;
139	        int result = uncappedLevel(owner);
140	        for (Owner member : members) {
141	            int level = uncappedLevel(member);
142	            if (runningMax != null) {
143	                level = Math.min(level, runningMax + 1);
144	            }
145	            runningMax = (runningMax == null) ? level : Math.max(runningMax, level);
146	            if (member.getId().equals(id)) {
147	                result = level;
148	            }
149	        }
150	        return result;
151	    }
152	
153	    /**
154	     * Map {@link #membershipPoints(Owner)} to a membership level from 1 to 4: level 1 for 0-1
155	     * points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
156	     */
157	    private int uncappedLevel(Owner owner) {
158	        int points = membershipPoints(owner);
159	        if (points <= 1) {
160	            return 1;
161	        }
162	        if (points <= 3) {
163	            return 2;
164	        }
165	        if (points <= 5) {
166	            return 3;
167	        }
168	        return 4;
169	    }
170	
171	    /**
172	     * The number of owners in this owner's household, identified by the shared {@code householdId}
173	     * assigned at creation. An owner with no householdId counts only as itself.
174	     */
175	    protected long householdSize(Owner owner) {
176	        String householdId = owner.getHouseholdId();
177	        if (householdId == null) {
178	            return 1;
179	        }
180	        long count = 0;
181	        for (Owner existing : ownerRepository.findAll()) {
182	            if (householdId.equals(existing.getHouseholdId())) {
183	                count++;
184	            }
185	        }
186	        return count;
187	    }
188	
189	    /**
190	     * Derive the owner's preferred contact channel: {@code EMAIL} when an email is present,
191	     * otherwise {@code PHONE}.
192	     */
193	    protected String contactPreference(Owner owner) {
194	        return (owner.getEmail() != null && !owner.getEmail().isEmpty()) ? "EMAIL" : "PHONE";
195	    }
196	
197	    /**
198	     * Derive the owner's age band from {@code birthDate} as at {@code registrationDate}:
199	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, {@code SENIOR} at 65 or over.
200	     * Returns {@code null} when no birth date was supplied.
201	     */
202	    protected String ageBand(Owner owner) {
203	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
204	            return null;
205	        }
206	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
207	        if (age < 18) {
208	            return "MINOR";
209	        }
210	        if (age < 65) {
211	            return "ADULT";
212	        }
213	        return "SENIOR";
214	    }
215	
216	    /**
217	     * The owner's fiscal year, formatted {@code FY<YY>} (last two digits) and derived from the
218	     * business-day-adjusted {@code registrationDate}; the fiscal year starts on 1 July. Returns
219	     * {@code null} when no registration date is set.
220	     */
221	    protected String fiscalYear(Owner owner) {
222	        return owner.getRegistrationDate() == null ? null
223	                : org.springframework.samples.petclinic.rest.function.owner.FiscalYear
224	                        .label(owner.getRegistrationDate());
225	    }
226	
227	    /**
228	     * Known country codes (digits after the {@code '+'}), longest first so {@code '61'} is
229	     * matched before {@code '1'}, mirroring {@code NormalizeOwnerTelephone}.
230	     */
231	    private static final String[] COUNTRY_CODES = {"61", "1"};
232	
233	    /**
234	     * Format the stored E.164 telephone for humans: the country code, a space, then the national
235	     * digits grouped in threes from the left (e.g. {@code +61412345678} -> {@code +61 412 345 678}).
236	     * Returns the raw value unchanged when it is not a recognised E.164 number.
237	     */
238	    protected String telephoneDisplay(Owner owner) {
239	        String telephone = owner.getTelephone();
240	        if (telephone == null || !telephone.startsWith("+")) {
241	            return telephone;
242	        }
243	        String digits = telephone.substring(1);
244	        String code = null;
245	        for (String candidate : COUNTRY_CODES) {
246	            if (digits.startsWith(candidate)) {
247	                code = candidate;
248	                break;
249	            }
250	        }
251	        if (code == null) {
252	            return telephone;
253	        }
254	        String national = digits.substring(code.length());
255	        StringBuilder grouped = new StringBuilder("+").append(code);
256	        for (int i = 0; i < national.length(); i += 3) {
257	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
258	        }
259	        return grouped.toString();
260	    }
261	
262	    /**
263	     * Compute a single Luhn check digit (0-9) over the digits contained in the owner's
264	     * {@code customerCode}. Non-digit characters (such as the hyphen separators) are ignored.
265	     */
266	    protected Integer checkDigit(Owner owner) {
267	        String code = owner.getCustomerCode();
268	        if (code == null) {
269	            return null;
270	        }
271	        int sum = 0;
272	        boolean dbl = true;
273	        for (int i = code.length() - 1; i >= 0; i--) {
274	            char c = code.charAt(i);
275	            if (c < '0' || c > '9') {
276	                continue;
277	            }
278	            int d = c - '0';
279	            if (dbl) {
280	                d *= 2;
281	                if (d > 9) {
282	                    d -= 9;
283	                }
284	            }
285	            sum += d;
286	            dbl = !dbl;
287	        }
288	        return (10 - (sum % 10)) % 10;
289	    }
290	}
